export type Message = { content: string };
export const defaults = { maxChars: 12000, keepRecent: 6 };
/** Remove oldest messages until the remaining text fits the character budget. No extra model call. */
export function trimOldest(messages: Message[], maxChars = defaults.maxChars): Message[] {
  const result = [...messages];
  while (result.length && result.reduce((n, m) => n + m.content.length, 0) > maxChars) result.shift();
  return result;
}
/** Keep a generated summary of older messages plus the latest messages. Summary generation costs one extra model call. */
export async function foldHistory(
  messages: Message[],
  makeSummary: (old: Message[]) => Promise<string>,
  keepRecent = defaults.keepRecent,
): Promise<Message[]> {
  if (messages.length <= keepRecent) return messages;
  const summary = await makeSummary(messages.slice(0, -keepRecent));
  return [{ content: summary }, ...messages.slice(-keepRecent)];
}

content.text:
Две стратегии освобождения места в истории:

**`trimOldest()`** — удаляет самые старые сообщения, пока размер не станет ≤ `maxChars` (по умолчанию 12000 символов). Никаких дополнительных вызовов модели, но **теряет контекст**.

**`foldHistory()`** — сжимает старые сообщения в одно summary-сообщение, сохраняет последние `keepRecent` сообщений (по умолчанию 6). Требует **один дополнительный вызов модели** на создание summary.

Настройки:
- `defaults.maxChars` — бюджет символов истории
- `defaults.keepRecent` — сколько последних сообщений гарантированно сохранять

**Если важно сохранить договорённости из начала разговора** — выбирай **`foldHistory()`**. Договорённости обычно в начале сессии, и foldHistory создаёт из них summary, который остаётся в истории. `trimOldest()` просто выкинет их.

Пример использования:
```ts
// Теряет начало: договорённости удалятся
const trimmed = trimOldest(messages);

// Сохраняет начало: договорённости в summary
const folded = await foldHistory(messages, async (old) => 
  model.summarize(old)
);
```
